"""Cache only formulas generated by this app, not arbitrary imported Excel formulas."""
import re,zipfile,tempfile,os
from decimal import Decimal,ROUND_HALF_UP
from pathlib import Path
from xml.etree import ElementTree as ET

def write_generated_caches(wb,case,path):
    cache={};active=set();primary=case.applicants[0]
    def value(sheet,coord):
        key=(sheet,coord.replace('$',''))
        if key in cache:return cache[key]
        if key in active:raise ValueError('Generated formula cycle: '+str(key))
        cell=wb[key[0]][key[1]]
        if cell.data_type!='f':return cell.value or 0
        active.add(key);formula=cell.value;result=None
        if sheet=='Sheet1' and coord in ('B3','C3','B7','F8','G2','G3'):
            if coord=='B3':result=primary.title+' '+primary.name
            elif coord=='C3':result=case.parent_line(primary)
            elif coord=='B7':result=primary.title+' '+primary.name+(' & '+case.applicants[1].title+' '+case.applicants[1].name if len(case.applicants)>1 else '')
            elif coord=='F8':result='('+str(wb['Sheet1']['F5'].value or '')+str(wb['Sheet1']['F3'].value or '')+')'
            elif coord=='G2':result=' He wants to go to' if primary.title=='Mr.' else ' She wants to go to'
            else:result=' '+{'CAD$':'Canada','AUD$':'Australia','USD$':'USA','UK£':'UK','EUR€':'Europe'}.get(wb['Sheet1']['B6'].value,'')
        elif formula=='=0':result=0
        elif formula.startswith('=SUM('):
            m=re.fullmatch(r'=SUM\(([A-Z]+)(\d+):([A-Z]+)(\d+)\)',formula)
            if not m or m[1]!=m[3]:raise ValueError('Unknown generated SUM formula.')
            result=sum(Decimal(str(value(sheet,m[1]+str(i)))) for i in range(int(m[2]),int(m[4])+1))
        elif formula.startswith('=IF(Sheet1!$C$6>0,ROUND('):
            ref=re.search(r'ROUND\(([A-Z]+\d+)/',formula)[1];rate=Decimal(str(wb['Sheet1']['C6'].value or 0))
            result=(Decimal(str(value(sheet,ref)))/rate).quantize(Decimal('1'),rounding=ROUND_HALF_UP) if rate>0 else 0
        elif formula.startswith('=CONCATENATE(Sheet1!A'):
            refs=re.findall(r'Sheet1!([AB]\d+)',formula);result=' '.join(str(value('Sheet1',r)) for r in refs)
        elif re.fullmatch(r"='[^']+'![A-Z]+\d+",formula):
            m=re.fullmatch(r"='([^']+)'!([A-Z]+\d+)",formula);result=value(m[1],m[2])
        elif re.fullmatch(r'=[A-Z]+\d+',formula):result=value(sheet,formula[1:])
        elif re.fullmatch(r'=[A-Z]+\d+(?:[+-][A-Z]+\d+)+',formula):
            result=Decimal(0)
            for sign,ref in re.findall(r'([+-]?)([A-Z]+\d+)',formula[1:]):result+=Decimal(str(value(sheet,ref)))*(-1 if sign=='-' else 1)
        if result is None:raise ValueError('Unsupported app-generated formula: '+sheet+'!'+coord)
        active.remove(key);cache[key]=result;return result
    for sh in wb:
        for row in sh:
            for cell in row:
                if cell.data_type=='f':value(sh.title,cell.coordinate)
    ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'};tag='{'+ns['s']+'}'
    fd,temp=tempfile.mkstemp(suffix='.xlsx',dir=Path(path).parent);os.close(fd)
    try:
        with zipfile.ZipFile(path) as original,zipfile.ZipFile(temp,'w',zipfile.ZIP_DEFLATED) as result:
            for entry in original.infolist():
                data=original.read(entry.filename)
                m=re.fullmatch(r'xl/worksheets/sheet(\d+)\.xml',entry.filename)
                if m:
                    name=wb.worksheets[int(m[1])-1].title;tree=ET.fromstring(data)
                    for cell in tree.findall('.//s:c',ns):
                        key=(name,cell.attrib['r'])
                        if key not in cache:continue
                        val=cache[key];v=cell.find(tag+'v')
                        if v is None:v=ET.SubElement(cell,tag+'v')
                        if isinstance(val,str):cell.set('t','str');v.text=val
                        else:cell.pop('t',None) if hasattr(cell,'pop') else cell.attrib.pop('t',None);v.text=str(val)
                    data=ET.tostring(tree,encoding='utf-8',xml_declaration=True)
                result.writestr(entry,data)
        Path(temp).replace(path)
    finally:Path(temp).unlink(missing_ok=True)
